addon.localeData.frFR.generalTexts.CURTSEY = { gruppe = { "Les bonnes manières survivent aux plus longs voyages.", "Un geste courtois ouvre bien des portes." }, ziel = { "%s, un geste courtois ouvre bien des portes.", "%s: Les bonnes manières survivent aux plus longs voyages." } }
addon.localeData.frFR.generalTexts.DISAPPOINTED = { gruppe = { "Ce n'est pas tout à fait ce que j'imaginais.", "Une promesse devrait être plus qu'un joli son." }, ziel = { "%s, une promesse devrait être plus qu'un joli son.", "%s: Ce n'est pas tout à fait ce que j'imaginais." } }
addon.localeData.frFR.generalTexts.DOH = { gruppe = { "Par les ancêtres, comment ai-je pu manquer cela ?", "Mon idée brillante est arrivée trop tard." }, ziel = { "%s, mon idée brillante est arrivée trop tard.", "%s: Par les ancêtres, comment ai-je pu manquer cela ?" } }
addon.localeData.frFR.generalTexts.DOOM = { gruppe = { "Voilà une fin qui ne recevra guère d'applaudissements.", "J'ai un terrible pressentiment." }, ziel = { "%s, j'ai un terrible pressentiment.", "%s: Voilà une fin qui ne recevra guère d'applaudissements." } }
addon.localeData.frFR.generalTexts.DROOL = { gruppe = { "Cette odeur vaut tous les arguments.", "Qui a caché ce merveilleux repas ?" }, ziel = { "%s, qui a caché ce merveilleux repas ?", "%s: Cette odeur vaut tous les arguments." } }
addon.localeData.frFR.generalTexts.DUCK = { gruppe = { "Baissez la tête, tout de suite !", "Les questions attendront le prochain mur." }, ziel = { "%s, les questions attendront le prochain mur.", "%s: Baissez la tête, tout de suite !" } }
addon.localeData.frFR.generalTexts.EAT = { gruppe = { "Le ventre plein rend le monde plus aimable.", "Je me souviendrai de ce rôti." }, ziel = { "%s, je me souviendrai de ce rôti.", "%s: Le ventre plein rend le monde plus aimable." } }
addon.localeData.frFR.generalTexts.EYE = { gruppe = { "Je vais garder cela à l'œil, par prudence.", "Certaines réponses sont juste devant nous." }, ziel = { "%s, certaines réponses sont juste devant nous.", "%s: Je vais garder cela à l'œil, par prudence." } }
addon.localeData.frFR.generalTexts.FAREWELL = { gruppe = { "Que vos routes soient sûres et vos haltes chaleureuses.", "Nous nous retrouverons au prochain carrefour." }, ziel = { "%s, nous nous retrouverons au prochain carrefour.", "%s: Que vos routes soient sûres et vos haltes chaleureuses." } }
addon.localeData.frFR.generalTexts.FEAST = { gruppe = { "Un bon festin demande des amis affamés.", "Ce soir personne ne lésine sur le dessert." }, ziel = { "%s, ce soir personne ne lésine sur le dessert.", "%s: Un bon festin demande des amis affamés." } }
addon.localeData.frFR.generalTexts.FEAR = { gruppe = { "Certaines ombres ne méritent aucune curiosité.", "Restez près de moi. Quelque chose cloche." }, ziel = { "%s, restez près de moi. Quelque chose cloche.", "%s: Certaines ombres ne méritent aucune curiosité." } }
addon.localeData.frFR.generalTexts.FIDGET = { gruppe = { "Mes mains n'ont plus aucune patience.", "Attendre peut être épuisant." }, ziel = { "%s, attendre peut être épuisant.", "%s: Mes mains n'ont plus aucune patience." } }
addon.localeData.frFR.generalTexts.FLAP = { gruppe = { "Des ailes seraient bien pratiques en ce moment.", "Je devrais peut-être apprendre à atterrir d'abord." }, ziel = { "%s, je devrais peut-être apprendre à atterrir d'abord.", "%s: Des ailes seraient bien pratiques en ce moment." } }
addon.localeData.frFR.generalTexts.FLEE = { gruppe = { "La retraite est un art sous-estimé !", "Qui veut vivre plus longtemps ferait mieux de courir." }, ziel = { "%s, qui veut vivre plus longtemps ferait mieux de courir.", "%s: La retraite est un art sous-estimé !" } }
addon.localeData.frFR.generalTexts.FLEX = { gruppe = { "Ces muscles ne viennent pas de la lecture.", "Un peu de vantardise devrait être permis." }, ziel = { "%s, un peu de vantardise devrait être permis.", "%s: Ces muscles ne viennent pas de la lecture." } }
addon.localeData.frFR.generalTexts.FLOP = { gruppe = { "La gravité a gagné pour aujourd'hui.", "Le sol m'a invité avec beaucoup de conviction." }, ziel = { "%s, le sol m'a invité avec beaucoup de conviction.", "%s: La gravité a gagné pour aujourd'hui." } }
addon.localeData.frFR.generalTexts.FOLLOWME = { gruppe = { "Suivez-moi, je connais au moins un chemin.", "Restez groupés, le sentier est étroit." }, ziel = { "%s, restez groupés, le sentier est étroit.", "%s: Suivez-moi, je connais au moins un chemin." } }
addon.localeData.frFR.generalTexts.FOOD = { gruppe = { "Le courage seul ne remplit pas l'estomac.", "Quelqu'un aurait un morceau de pain ?" }, ziel = { "%s, quelqu'un aurait un morceau de pain ?", "%s: Le courage seul ne remplit pas l'estomac." } }
addon.localeData.frFR.generalTexts.FROWN = { gruppe = { "Cela ne me plaît pas du tout.", "Les mauvaises nouvelles méritent un long regard." }, ziel = { "%s, les mauvaises nouvelles méritent un long regard.", "%s: Cela ne me plaît pas du tout." } }
addon.localeData.frFR.generalTexts.GASP = { gruppe = { "Par toutes les puissances, quelle surprise !", "Il me faudra un instant pour comprendre." }, ziel = { "%s, il me faudra un instant pour comprendre.", "%s: Par toutes les puissances, quelle surprise !" } }
addon.localeData.frFR.generalTexts.GAZE = { gruppe = { "Certaines choses méritent un second regard.", "Toute une histoire nous attend là-bas." }, ziel = { "%s, toute une histoire nous attend là-bas.", "%s: Certaines choses méritent un second regard." } }
addon.localeData.frFR.generalTexts.GLAD = { gruppe = { "Aujourd'hui est un beau jour pour des retrouvailles.", "Comme il est bon que le monde réponde avec gentillesse." }, ziel = { "%s, comme il est bon que le monde réponde avec gentillesse.", "%s: Aujourd'hui est un beau jour pour des retrouvailles." } }
addon.localeData.frFR.generalTexts.GLARE = { gruppe = { "Un seul regard devrait suffire comme avertissement.", "Réfléchissez bien au prochain geste." }, ziel = { "%s, réfléchissez bien au prochain geste.", "%s: Un seul regard devrait suffire comme avertissement." } }
addon.localeData.frFR.generalTexts.GLOAT = { gruppe = { "Je déteste me vanter. Mais c'était magnifique.", "Accordez-moi ce petit moment de triomphe." }, ziel = { "%s, accordez-moi ce petit moment de triomphe.", "%s: Je déteste me vanter. Mais c'était magnifique." } }
addon.localeData.frFR.generalTexts.GOLFCLAP = { gruppe = { "Des applaudissements très mesurés semblent appropriés.", "Ce fut tout de même une tentative." }, ziel = { "%s, ce fut tout de même une tentative.", "%s: Des applaudissements très mesurés semblent appropriés." } }
addon.localeData.frFR.generalTexts.GRIN = { gruppe = { "Je viens d'avoir une idée particulièrement amusante.", "Ce sourire ne révèle absolument rien." }, ziel = { "%s, ce sourire ne révèle absolument rien.", "%s: Je viens d'avoir une idée particulièrement amusante." } }
addon.localeData.frFR.generalTexts.GROAN = { gruppe = { "La journée va être très longue.", "Pouvons-nous au moins compter les mauvaises idées ?" }, ziel = { "%s, pouvons-nous au moins compter les mauvaises idées ?", "%s: La journée va être très longue." } }
addon.localeData.frFR.generalTexts.GROVEL = { gruppe = { "Ma dignité ne vaut plus très cher aujourd'hui.", "Si l'humilité aide, je commence immédiatement." }, ziel = { "%s, si l'humilité aide, je commence immédiatement.", "%s: Ma dignité ne vaut plus très cher aujourd'hui." } }
addon.localeData.frFR.generalTexts.GUFFAW = { gruppe = { "C'était la meilleure plaisanterie depuis la dernière bataille !", "J'en rirai pendant des jours." }, ziel = { "%s, j'en rirai pendant des jours.", "%s: C'était la meilleure plaisanterie depuis la dernière bataille !" } }
addon.localeData.frFR.generalTexts.HAPPY = { gruppe = { "La vie nous offre un bel instant.", "Ne laissons pas passer cette belle journée." }, ziel = { "%s, ne laissons pas passer cette belle journée.", "%s: La vie nous offre un bel instant." } }
addon.localeData.frFR.generalTexts.HEALME = { gruppe = { "Je suis blessé, pas taillé dans la pierre !", "Un soigneur vaudrait de l'or ici." }, ziel = { "%s, un soigneur vaudrait de l'or ici.", "%s: Je suis blessé, pas taillé dans la pierre !" } }
addon.localeData.frFR.generalTexts.HELPME = { gruppe = { "J'aurais vraiment besoin d'aide ici !", "Que ceux qui ont les mains libres se manifestent." }, ziel = { "%s, que ceux qui ont les mains libres se manifestent.", "%s: J'aurais vraiment besoin d'aide ici !" } }
addon.localeData.frFR.generalTexts.HUNGRY = { gruppe = { "Mes pensées tournent uniquement autour de la nourriture.", "Un ragoût chaud serait une grande victoire." }, ziel = { "%s, un ragoût chaud serait une grande victoire.", "%s: Mes pensées tournent uniquement autour de la nourriture." } }
addon.localeData.frFR.generalTexts.IMPATIENT = { gruppe = { "Ma patience vient de partir en vacances.", "Si nous attendons encore, l'herbe va pousser ici." }, ziel = { "%s, si nous attendons encore, l'herbe va pousser ici.", "%s: Ma patience vient de partir en vacances." } }
